    def oxford_join_numbers(numbers):
        str_numbers = [str(n) for n in numbers]
        if len(str_numbers) == 0:
            return ''
        elif len(str_numbers) == 1:
            return str_numbers[0]
        elif len(str_numbers) == 2:
            return f"{str_numbers[0]} and {str_numbers[1]}"
        else:
            return ', '.join(str_numbers[:-1]) + ', and ' + str_numbers[-1]
