def oxford_join_numbers(numbers):
    count = len(numbers)
    if count == 0:
        return ''
    elif count == 1:
        return str(numbers[0])
    elif count == 2:
        return f"{numbers[0]} and {numbers[1]}"
    else:
        return f"{', '.join(map(str, numbers[:-1]))} and {numbers[-1]}"
